import{_ as t,o as s,c as a,a3 as r}from"./chunks/framework.BZKbe9n2.js";const m=JSON.parse('{"title":"Raumfeld speakers","description":"","frontmatter":{},"headers":[],"relativePath":"administration/speakers.md","filePath":"administration/speakers.md"}'),o={name:"administration/speakers.md"};function n(h,e,d,i,p,l){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="raumfeld-speakers" tabindex="-1">Raumfeld speakers <a class="header-anchor" href="#raumfeld-speakers" aria-label="Permalink to &quot;Raumfeld speakers&quot;">​</a></h1><p>Anthology plays on Teufel Raumfeld speakers. The server needs to find the Raumfeld host, and the speakers need to reach the server.</p><h2 id="finding-the-raumfeld-host" tabindex="-1">Finding the Raumfeld host <a class="header-anchor" href="#finding-the-raumfeld-host" aria-label="Permalink to &quot;Finding the Raumfeld host&quot;">​</a></h2><ul><li><strong>With host networking</strong> (<code>Network=host</code> in <code>anthology.pod</code>, <code>network_mode: host</code> in Compose), the server finds the Raumfeld host automatically by multicast (SSDP).</li><li><strong>Without host networking</strong> (the default rootless pod), multicast does not reach the server. Enter the address of the Raumfeld host in <strong>Settings › Speakers</strong> – the IP address of the base or of the speaker that serves as host – or set <code>ANTHOLOGY_RAUMFELD_HOSTS</code>.</li></ul><p><strong>Settings › Speakers</strong> shows every system with its state, and the reason when it cannot be reached.</p><h2 id="speakers-reaching-the-server" tabindex="-1">Speakers reaching the server <a class="header-anchor" href="#speakers-reaching-the-server" aria-label="Permalink to &quot;Speakers reaching the server&quot;">​</a></h2><p>The speakers fetch the music from the server over HTTP. Set <code>ANTHOLOGY_OUTPUT_MEDIA_URL</code> to the server&#39;s address as the speakers see it, for example <code>http://192.168.1.10:8400</code>. Without it, the server uses its own address on the route to the speakers – behind the pod&#39;s port forwarding that is the container&#39;s address, so set the URL there.</p><p>Speakers and server must be in the same local network; no port needs to be opened to the internet.</p><p>How to play on speakers: <a href="/anthology/next/guide/speakers">Playing on speakers</a>.</p>',9)])])}const f=t(o,[["render",n]]);export{m as __pageData,f as default};
